<?php
require_once __DIR__.'/../../includes/functions.php';require_admin();$error='';$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);$status=(string)($_POST['status']??'');$response=trim((string)($_POST['admin_response']??''));$amount=trim((string)($_POST['quote_amount']??''));$details=trim((string)($_POST['quote_details']??''));if(!$id||!in_array($status,['new','quoted','accepted','in_progress','completed','declined'],true))$error='Invalid request update.';else{$pdo=db();$pdo->beginTransaction();try{$pdo->prepare('UPDATE service_requests SET status=?,admin_response=? WHERE id=?')->execute([$status,$response?:null,$id]);if($amount!==''||$details!==''){if(!is_numeric($amount)||(float)$amount<0||$details==='')throw new RuntimeException('Enter a valid quote amount and description.');$pdo->prepare("INSERT INTO quotations (request_id,amount,details,status,valid_until) VALUES (?,?,?,'sent',DATE_ADD(CURDATE(),INTERVAL 30 DAY))")->execute([$id,$amount,$details]);$pdo->prepare("UPDATE service_requests SET status='quoted' WHERE id=?")->execute([$id]);}$pdo->commit();$notice='Service request updated.';}catch(Throwable $exception){if($pdo->inTransaction())$pdo->rollBack();$error=$exception instanceof RuntimeException?$exception->getMessage():'Service request could not be updated.';error_log('Service request update failed: '.$exception->getMessage());}}}
$rows=db()->query('SELECT sr.*,s.name AS service_name FROM service_requests sr LEFT JOIN services s ON s.id=sr.service_id ORDER BY sr.created_at DESC LIMIT 150')->fetchAll();$adminTitle='Service requests · Yucca Fabrics';require __DIR__.'/../../includes/admin-header.php';
?>
<h1 class="font-serif text-4xl">Service requests & quotations</h1><?php if($error||$notice): ?><p class="mt-4 rounded p-3 text-sm <?= $error?'bg-red-50 text-red-800':'bg-green-50 text-green-800' ?>"><?= e($error?:$notice) ?></p><?php endif; ?><div class="mt-6 space-y-4"><?php foreach($rows as $row): ?><article class="grid gap-5 bg-white p-5 lg:grid-cols-[1fr_1fr]"><div><p class="font-serif text-2xl"><?= e($row['service_name']??'Project enquiry') ?></p><p class="mt-2 text-sm"><?= e($row['name']) ?> · <?= e($row['email']) ?> · <?= e($row['phone']) ?></p><p class="mt-1 text-sm text-gray-600"><?= e($row['location']) ?><?= $row['preferred_date']?' · preferred '.e(date('M j, Y',strtotime($row['preferred_date']))):'' ?></p><p class="mt-3 whitespace-pre-line text-sm leading-6"><?= e($row['description']) ?></p><p class="mt-3 text-xs capitalize text-gray-500">Status: <?= e(str_replace('_',' ',$row['status'])) ?></p><?php $images=db()->prepare('SELECT image FROM service_request_images WHERE request_id=?');$images->execute([$row['id']]);foreach($images->fetchAll() as $image): ?><a href="<?= e(url('uploads/service-requests/'.rawurlencode(basename($image['image'])))) ?>" target="_blank" rel="noopener" class="mt-3 inline-block underline text-sm">View reference photo</a><?php endforeach; ?></div><form method="post" class="grid content-start gap-3"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><label class="text-sm">Status<select name="status" class="form-control mt-1"><?php foreach(['new','quoted','accepted','in_progress','completed','declined'] as $status): ?><option value="<?= e($status) ?>" <?= $row['status']===$status?'selected':'' ?>><?= e(ucwords(str_replace('_',' ',$status))) ?></option><?php endforeach; ?></select></label><label class="text-sm">Customer response<textarea class="form-control mt-1" name="admin_response" rows="2"><?= e($row['admin_response']??'') ?></textarea></label><details><summary class="cursor-pointer text-sm font-semibold">Add a quotation</summary><label class="mt-3 block text-sm">Quote amount<input class="form-control mt-1" name="quote_amount" type="number" step=".01" min="0"></label><label class="mt-3 block text-sm">Quote details<textarea class="form-control mt-1" name="quote_details" rows="2"></textarea></label></details><button class="w-fit rounded-full bg-forest px-5 py-2 text-sm text-white">Save response</button></form></article><?php endforeach; ?></div>
<?php require __DIR__.'/../../includes/admin-footer.php'; ?>
